"""Inputs for the `fn/CharacterPosition` unit.

The state block is pinned at the character-handle global
(`0x1442a0bc0`, v2b `0x7ff7c8fc0bc0`) and contains the table
(space 0 -> record 0, space 1 -> null, space 2 -> a
count-0 record), the two records and the 8-entry array.

Handles are built as `space << 0x30 | generation << 0x20 | index`. The first
cases take every failure edge (space bound, sentinel index, null record,
empty record, negative index, index at/over count, entry index mismatch,
generation mismatch); the rest resolve live entries.

The function returns a vec4 in XMM0; the harness compares the full 128-bit
register, lane payloads included.
"""

from __future__ import annotations

import struct
from typing import List

from emu_oracle import ArgSpec

STATE_BASE = 0x00007ff7c8fc0bc0
STATE_LEN = 0x800
STATE_HEX = ""
CASES = [30064771072, 30064771079, 4611404573515448320, 34359738367, 281505041481728, 562980018192384, 32212254720, 30064771080, 30064771081, 30064771077, 38654705670, 30064771073, 30064771074, 30064771075, 30064771076, 30064771078, 34359738368, 32212254719]


def make_args(i: int) -> List[ArgSpec]:
    return [
        ArgSpec(kind="u64", bits=CASES[i % len(CASES)]),
        ArgSpec(kind="ptr", mem=bytes.fromhex(STATE_HEX), arena_offset=0x6000),
        ArgSpec(kind="u64", bits=STATE_BASE),
    ]
